import React, { useEffect, useState } from 'react';
import { API_BASE, approvalsApi } from '../../services/api';
import PageHeader from '../../components/shared/PageHeader';
import { useToast } from '../../context/ToastContext';

export default function ApprovalsPage() {
  const toast = useToast();
  const [approvals, setApprovals] = useState([]);
  const [loading, setLoading] = useState(false);

  const load = async () => {
    setLoading(true);
    try {
      const res = await approvalsApi.list();
      setApprovals(res.data || []);
    } catch (err) {
      console.error(err);
      toast(err?.response?.data?.error || 'Failed to load approvals', 'error');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { load(); }, []);

  const handleApprove = async (approvalId) => {
    const adminCert = window.localStorage.getItem('userCert') || 'ngoAdmin';
    if (!confirm(`Approve ${approvalId} ?`)) return;
    const verificationNote = window.prompt('Optional verification note for this approval', '') || '';
    try {
      await approvalsApi.approve({ approvalId, adminCert, verificationNote });
      await load();
      toast('Approved', 'success');
    } catch (err) {
      console.error(err);
      toast(err?.response?.data?.error || 'Approve failed', 'error');
    }
  };

  return (
    <div>
      <PageHeader title="Approvals (Admin)" />
      <div>
        {loading && <div>Loading...</div>}
        {!loading && approvals.length === 0 && <div>No approvals</div>}
        <table style={{ width: '100%', borderCollapse: 'collapse' }}>
          <thead>
            <tr>
              <th>Id</th>
              <th>Token</th>
              <th>NGO</th>
              <th>Amount</th>
              <th>Receipts</th>
              <th>Status</th>
              <th>Verified</th>
              <th>Created</th>
              <th>Action</th>
            </tr>
          </thead>
          <tbody>
            {approvals.map((a) => (
              <tr key={a.approvalId}>
                <td>{a.approvalId}</td>
                <td>{a.tokenId}</td>
                <td>{a.ngoId}</td>
                <td>{a.amount}</td>
                <td>
                  {Array.isArray(a.receipts) && a.receipts.length > 0 ? (
                    <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap' }}>
                      {a.receipts.map((receipt) => (
                        <a
                          key={receipt.receiptId || receipt.fileUrl}
                          href={`${API_BASE}${receipt.fileUrl}`}
                          target="_blank"
                          rel="noreferrer"
                          title={receipt.fileName || receipt.receiptId}
                        >
                          <img
                            src={`${API_BASE}${receipt.fileUrl}`}
                            alt={receipt.fileName || receipt.receiptId || 'receipt'}
                            style={{ width: 52, height: 52, objectFit: 'cover', borderRadius: 10, border: '1px solid var(--border)' }}
                          />
                        </a>
                      ))}
                    </div>
                  ) : (
                    <span style={{ color: 'var(--text-dim)' }}>None</span>
                  )}
                </td>
                <td>{a.status}</td>
                <td>{a.verifiedAt ? `Yes (${a.verifiedBy || 'admin'})` : 'Pending'}</td>
                <td>{a.createdAt}</td>
                <td>
                  {a.status === 'PENDING' && (
                    <button onClick={() => handleApprove(a.approvalId)}>Approve</button>
                  )}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}
